Sounds good. Let me first see what payments-svc is actually emitting so the monitors are grounded in real metric/tag names.

```json
{
  "tool": "datadog_api",
  "action": "metrics.list",
  "params": {
    "filter": "service:payments-svc",
    "from": "now-4h"
  }
}
```

```json
{
  "tool": "datadog_api",
  "action": "apm.services.get",
  "params": {
    "service": "payments-svc",
    "env": "production"
  }
}
```

```json
{
  "tool": "kubectl_query",
  "action": "get",
  "resource": "deployment",
  "namespace": "payments",
  "name": "payments-svc"
}
```

```json
{
  "tool": "pagerduty_api",
  "action": "services.list",
  "params": {
    "query": "payments"
  }
}
```

